// API utility functions for Creative Stock
const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

// Generic API call function
const apiCall = async (endpoint, options = {}) => {
  const url = `${API_BASE_URL}${endpoint}`;
  
  const config = {
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
    ...options,
  };

  try {
    const response = await fetch(url, config);
    const data = await response.json();
    
    if (!response.ok) {
      throw new Error(data.message || 'API request failed');
    }
    
    return data;
  } catch (error) {
    console.error(`API call failed: ${endpoint}`, error);
    throw error;
  }
};

// Pin-related API functions
export const pinApi = {
  // Get all pins with optional filtering
  getPins: (params = {}) => {
    const queryParams = new URLSearchParams(params);
    return apiCall(`/pins${queryParams.toString() ? `?${queryParams}` : ''}`);
  },

  // Get a specific pin by ID
  getPin: (id) => {
    return apiCall(`/pins/${id}`);
  },

  // Create a new pin
  createPin: (pinData) => {
    return apiCall('/pins', {
      method: 'POST',
      body: JSON.stringify(pinData),
    });
  },

  // Update an existing pin
  updatePin: (id, pinData) => {
    return apiCall(`/pins/${id}`, {
      method: 'PUT',
      body: JSON.stringify(pinData),
    });
  },

  // Delete a pin
  deletePin: (id) => {
    return apiCall(`/pins/${id}`, {
      method: 'DELETE',
    });
  },
};

// Category-related API functions
export const categoryApi = {
  // Get all categories
  getCategories: () => {
    return apiCall('/categories');
  },

  // Create a new category
  createCategory: (categoryData) => {
    return apiCall('/categories', {
      method: 'POST',
      body: JSON.stringify(categoryData),
    });
  },
};

// Admin-related API functions
export const adminApi = {
  // Admin login
  login: (credentials) => {
    return apiCall('/admin/login', {
      method: 'POST',
      body: JSON.stringify(credentials),
    });
  },
};

export default apiCall;
